+  const seen = new Set<string>();
+  for (const query of [...primary, ...secondary]) {
+    const lowered = query.query.trim().toLowerCase();
+    if (!lowered || seen.has(lowered)) {
+      continue;
+    }
+    seen.add(lowered);
+    combined.push(query);
+    if (combined.length >= MAX_DETERMINISTIC_SEARCH_QUERIES) {
+      break;
