         sandbox,
         action,
         policy,
         maxFileBytes,
         action.tool === 'diff_summary' ? input.authoritativeDiffSnapshot : undefined
       );
       usedTools.push(action.tool);
       recordEvidenceFromToolExecution(evidence, action, output.result, changedPathsSet);
       if (input.onLifecycleEvent) {
