     }

     if (finalValidationError) {
       throw finalValidationError;
     }
     throw new Error('Review analysis exceeded maximum step count');
   } finally {
     if (typeof sandbox.destroy === 'function') {
       try {
         await sandbox.destroy();
       } catch {
         // Best-effort cleanup only.
       }
     }
   }
 }

